    <script>
    // Prevent FOUC - Apply theme immediately
    (function() {
        var savedTheme = localStorage.getItem('darkMode');
        var isDark = savedTheme !== null ? savedTheme === 'true' : false; // Default to light mode

        if (isDark) {
            document.documentElement.classList.add('dark', 'dark-mode');
            if (document.body) {
                document.body.classList.add('dark-mode');
                document.body.classList.remove('bg-white');
            }
        }
    })();

    // EXTREME DEBUG & TOOLS TOGGLE
    console.log('✅ TOOLS SYSTEM: Initializing at the top...');
    window.toggleToolsMenu = function(e) {
        if (e && e.preventDefault) {
            e.preventDefault();
            e.stopPropagation();
        }
        var inner = document.getElementById('tools-dropdown-inner');
        var arrow = document.getElementById('tools-arrow-icon');

        if (inner) {
            if (inner.classList.contains('hidden')) {
                inner.classList.remove('hidden');
                inner.style.display = 'flex';
                if (arrow) arrow.classList.add('rotate-180');
                console.log('✅ TOOLS: Opened');
            } else {
                inner.classList.add('hidden');
                inner.style.display = 'none';
                if (arrow) arrow.classList.remove('rotate-180');
                console.log('✅ TOOLS: Closed');
            }
        } else {
            console.error('❌ TOOLS ERROR: Inner menu not found!');
        }
    };
    </script>
