        }

        /* Page Loader Styles */
        .loader-spinner {
            position: relative;
            width: 60px;
            height: 60px;
            margin: 0 auto;
        }

        .spinner-ring {
            width: 100%;
            height: 100%;
            border: 3px solid rgba(69, 128, 247, 0.2);
            border-top: 3px solid var(--primary-blue);
            border-radius: 50%;
            animation: spin 1.2s linear infinite;
        }

        @keyframes spin {
            0% { transform: rotate(0deg); }
            100% { transform: rotate(360deg); }
        }

        /* Mobile responsive loader */
        @media (max-width: 768px) {
            .loader-spinner {
                width: 50px;
                height: 50px;
            }

            .spinner-ring {
                border-width: 2.5px;
            }
        }

        @media (max-width: 480px) {
            .loader-spinner {
                width: 40px;
                height: 40px;
            }

            .spinner-ring {
                border-width: 2px;
            }
        }

