        <div class="p-6 flex-1 overflow-y-auto custom-scrollbar">



            <nav class="flex-grow flex flex-col">
    {# Identify the tool items (last two non-empty ones) #}
    {% set menuItems = [] %}
    {% for menu in site['menu'] %}{% if menu['name'] is not empty %}{% set menuItems = menuItems|merge([menu]) %}{% endif %}{% endfor %}

    {% set toolsCount = 2 %}
    {% set mainItemsCount = menuItems|length - toolsCount %}
    {% set toolItemsFound = [] %}
    {% set toolActive = false %}

    {% for i in range(0, menuItems|length - 1) %}
        {% set menu = menuItems[i] %}
        {% if i < mainItemsCount %}
            <a href="{{ menu['link'] }}" {% if menu['external'] %} target="_blank" {% endif %}
               class="{% if menu['active'] %}btn-custom-active text-white{% else %}group text-gray-700 hover:bg-indigo-50{% endif %} flex items-center gap-4 py-3 px-4 my-1 rounded-full font-medium transition-all duration-200">
                {% if menu['link'] == '/' %}<i class="ri-shopping-cart-line text-xl"></i>
                {% elseif menu['link'] == '/massorder' %}<i class="ri-instance-line text-xl"></i>
                {% elseif menu['link'] == '/orders' %}<i class="ri-file-list-3-line text-xl"></i>
                {% elseif menu['link'] == '/addfunds' %}<i class="ri-bank-card-line text-xl"></i>
                {% elseif menu['link'] == '/tickets' %}<i class="ri-coupon-3-line text-xl"></i>
                {% elseif menu['link'] == '/services' %}<i class="ri-list-check-2 text-xl"></i>
                {% elseif menu['link'] == '/contact' %}<i class="ri-contacts-book-line text-xl"></i>
                {% elseif menu['link'] == '/updates' %}<i class="ri-loop-left-line text-xl"></i>
                {% elseif menu['link'] == '/affiliates' %}<i class="ri-user-add-line text-xl"></i>
                {% elseif menu['link'] == '/child-panel' %}<i class="ri-price-tag-3-line text-xl"></i>
                {% elseif menu['link'] == '/api' %}<i class="ri-code-s-slash-line text-xl"></i>
                {% elseif menu['link'] == '/subscriptions' %}<i class="ri-time-line text-xl"></i>
                {% elseif menu['link'] == '/drip-feed' %}<i class="ri-drop-line text-xl"></i>
                {% elseif menu['link'] == '/orders/refunds' %}<i class="ri-exchange-dollar-line text-2xl"></i>
                {% elseif menu['link'] == '/recommended-services' %}<i class="ri-star-line text-xl"></i>
                {% elseif menu['link'] == '/createinvoice' %}<i class="ri-bill-line text-2xl"></i>
                {% elseif menu['link'] == 'https://t.me/smmexclusive_announcement' %}  <i class="ri-telegram-fill text-lg"></i>
                {% elseif menu['link'] == 'https://whatsapp.com/channel/0029VbC5o6FInlqGfflrlq1r' %}   <i class="ri-whatsapp-fill text-lg"></i>
                {% else %}<i class="ri-menu-line text-xl"></i>{% endif %}
                <span>{{ menu['name'] }}</span>
                <i class="ri-arrow-right-s-line ml-auto text-xl {% if not menu['active'] %}opacity-0 group-hover:opacity-100{% endif %} transition-opacity"></i>
            </a>
        {% else %}
            {% set toolItemsFound = toolItemsFound|merge([menu]) %}
            {% if menu['active'] %}{% set toolActive = true %}{% endif %}
        {% endif %}
    {% endfor %}

    {% if toolItemsFound|length > 0 %}
        <div class="relative mt-1 {% if toolActive %}tools-dropdown-active{% endif %}" id="tools-dropdown-container">
            <button id="tools-dropdown-toggle" onclick="window.toggleToolsMenu && window.toggleToolsMenu()" class="group text-gray-700 hover:bg-slate-50 flex items-center gap-4 py-3 px-4 my-1 rounded-full font-medium transition-all duration-200 w-full text-left">
                <i class="ri-tools-line text-xl group-hover:text-indigo-600 transition-colors"></i>
                <span>Tools</span>
                <i class="ri-arrow-down-s-line ml-auto text-xl transition-transform duration-300 {% if toolActive %}rotate-180{% endif %}" id="tools-arrow-icon"></i>
            </button>
            <div id="tools-dropdown-inner" class="{% if not toolActive %}hidden{% endif %} flex flex-col pl-4 mt-1 pb-2 space-y-1">
