    margin-bottom: -5px;
    border-width: 5px 5px 0;
    border-top-color: #000;
}
.tooltip.top-right .tooltip-arrow {
    bottom: 0;
    left: 5px;
    margin-bottom: -5px;
    border-width: 5px 5px 0;
    border-top-color: #000;
}
.tooltip.right .tooltip-arrow {
    top: 50%;
    left: 0;
    margin-top: -5px;
    border-width: 5px 5px 5px 0;
    border-right-color: #000;
}
.tooltip.left .tooltip-arrow {
    top: 50%;
    right: 0;
    margin-top: -5px;
    border-width: 5px 0 5px 5px;
    border-left-color: #000;
}
.tooltip.bottom .tooltip-arrow {
    top: 0;
    left: 50%;
    margin-left: -5px;
    border-width: 0 5px 5px;
    border-bottom-color: #000;
}
.tooltip.bottom-left .tooltip-arrow {
    top: 0;
    right: 5px;
    margin-top: -5px;
    border-width: 0 5px 5px;
    border-bottom-color: #000;
}
.tooltip.bottom-right .tooltip-arrow {
    top: 0;
    left: 5px;
    margin-top: -5px;
    border-width: 0 5px 5px;
    border-bottom-color: #000;
}

style.css:
@import url('https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700&display=swap');

/* General Styles */
:root {
    --primary-blue: #2563eb;
    --light-bg: #ffffff;
    --secondary-bg: #f8f9fa;
    --text-dark: #495057;
    --text-heading: #212529;
    --border-color: rgba(0, 0, 0, 0.08);
}

* {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
}

body {
    font-family: "Satoshi", system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Oxygen, Ubuntu, Cantarell, "Open Sans", "Helvetica Neue", sans-serif;    background-color: var(--light-bg);
    color: var(--text-dark);
    overflow-x: hidden;
    position: relative;
}

.page-wrapper {
    position: relative;
    z-index: 2;
    min-height: 100vh;
    display: flex;
    flex-direction: column;
}

.container {
    width: 100%;
    max-width: 1200px !important;
    margin: 0 auto;
    padding: 0 20px;
}

a {
    text-decoration: none;
    color: inherit;
}

ul {
    list-style: none;
}

h1, h2, h3, h4, h5, h6 {
    font-family: "Aeonik", "Satoshi", system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Oxygen, Ubuntu, Cantarell, "Open Sans", "Helvetica Neue", sans-serif;
}

/* Background Effects */
.background-effects {
    position: absolute;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    overflow: hidden;
    z-index: -1;
}

.stars {
    position: absolute;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    z-index: 0;
}

.star {
    position: absolute;
    background-color: #93c5fd; /* soft blue */
    border-radius: 50%;
    box-shadow: 0 0 5px #93c5fd, 0 0 10px #93c5fd;
    animation: moveStar linear infinite, twinkle ease-in-out infinite;
}

@keyframes twinkle {
    0%, 100% {
        opacity: 1;
        transform: scale(1);
    }
    50% {
        opacity: 0.2;
        transform: scale(0.5);
    }
}

@keyframes moveStar {
    0%, 100% {
        transform: translate(0, 0);
    }
    20% {
        transform: translate(20px, -30px);
    }
    40% {
        transform: translate(-25px, 25px);
    }
    60% {
        transform: translate(30px, 20px);
    }
    80% {
        transform: translate(-15px, -25px);
    }
}

.grid-overlay {
    position: absolute;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    background-image:
        linear-gradient(rgba(0,0,0,0.03) 1px, transparent 1px),
        linear-gradient(90deg, rgba(0,0,0,0.03) 1px, transparent 1px);
    background-size: 60px 60px;
}

.blur-orb {
    position: absolute;
    border-radius: 50%;
    filter: blur(140px);
    opacity: 0.25;
}

.orb1 { background-color: #00c6ff; width: 300px; height: 300px; top: -50px; left: -100px; }
.orb2 { background-color: #ff00aa; width: 250px; height: 250px; top: 200px; right: -50px; }
.orb3 { background-color: #39ff14; width: 200px; height: 200px; bottom: 100px; left: 10%; }
.orb4 { background-color: #ff8c00; width: 280px; height: 280px; bottom: -100px; right: 20%; }


/* Header */
.header {
    padding: 20px 0;
    position: sticky;
    top: 0px;
    z-index: 100;
}

.header-inner {
    display: flex;
    justify-content: space-between;
    align-items: center;
    background: rgba(255, 255, 255, 0.75);
    backdrop-filter: blur(10px);
    -webkit-backdrop-filter: blur(10px);
    border: 1px solid rgba(0, 0, 0, 0.05);
    border-radius: 9999px;
    padding: 12px 25px;
    box-shadow: 0 5px 25px rgba(0,0,0,0.07);
}

.logo {
    display: flex;
    align-items: center;
    gap: 10px;
    font-weight: 600;
    font-size: 1.2rem;
    color: var(--text-heading);
}

.logo img {
    border-radius: 8px;
}

.main-nav {
    display: none;
}

@media (min-width: 768px) {
    .main-nav {
        display: block;
    }
    .main-nav ul {
        display: flex;
        align-items: center;
        gap: 20px;
    }
}

.main-nav a {
    font-size: 14px;
    font-weight: 500;
    color: var(--text-dark);
    transition: color 0.3s ease;
    display: flex;
    align-items: center;
    gap: 8px;
}

.main-nav a svg {
    width: 14px;
    height: 14px;
}

.main-nav a:hover {
    color: var(--primary-blue);
}

.main-nav .separator {
    width: 4px;
    height: 4px;
    background-color: rgba(0, 0, 0, 0.15);
    border-radius: 50%;
}

.header-actions {
    display: flex;
    gap: 12px;
    align-items: center;
}

.btn {
    padding: 10px 20px;
    border-radius: 9999px;
    font-weight: 500;
    display: inline-flex;
    align-items: center;
    gap: 8px;
    transition: all 0.3s ease;
    border: 1px solid transparent;
    cursor: pointer;
}

.btn-primary {
    background-color: var(--primary-blue);
    color: #ffffff;
    box-shadow: 0 4px 15px rgba(37, 99, 235, 0.2);
}

.btn-primary:hover {
    transform: translateY(-2px);
    box-shadow: 0 6px 20px rgba(37, 99, 235, 0.3);
}

.btn-secondary {
    background-color: var(--secondary-bg);
    border: 1px solid var(--border-color);
    color: var(--text-heading);
}

.btn-secondary:hover {
    background-color: #e9ecef;
    border-color: #dee2e6;
}

.btn-tertiary {
    background-color: transparent;
    border: 1px solid var(--border-color);
    color: var(--text-heading);
}

.btn-tertiary:hover {
     background-color: var(--secondary-bg);
}

/* Main Content */
main {
    flex-grow: 1;
    display: flex;
    align-items: center;
    justify-content: center;
}

.hero {
    width: 100%;
    text-align: center;
    padding-top: 60px;
    position: relative; /* Add relative positioning */
}

/* Floating Widgets */
.floating-widget {
    background: rgba(255, 255, 255, 0.75);
    border: 1px solid rgba(0, 0, 0, 0.05);
    border-radius: 9999px; /* pill shape */
    padding: 12px 20px 12px 12px;
    position: absolute;
    z-index: 5;
    backdrop-filter: blur(12px);
    -webkit-backdrop-filter: blur(12px);
    box-shadow: 0 10px 40px rgba(0,0,0,0.1);
    animation: float 6s ease-in-out infinite;
    color: var(--text-dark);
    text-align: left;
    display: flex;
    align-items: center;
    gap: 12px;
    font-weight: 500;
    font-size: 0.95rem;
}

.avatar-container {
    position: relative;
    display: flex;
    align-items: center;
    justify-content: center;
}

.widget-avatar {
    width: 44px;
    height: 44px;
    border-radius: 50%;
    object-fit: cover;
}

.social-icon-badge {
    position: absolute;
    bottom: -2px;
    right: -4px;
    width: 22px;
    height: 22px;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    border: 2px solid #ffffff;
}

.social-icon-badge.instagram {
    background: radial-gradient(circle at 30% 107%, #fdf497 0%, #fdf497 5%, #fd5949 45%,#d6249f 60%,#285AEB 90%);
    color: white;
}

.social-icon-badge.tiktok {
    background: #000;
    color: #fff;
}

.social-icon-badge.twitter {
    background: #1DA1F2;
    color: #fff;
}

.social-icon-badge i {
    font-size: 0.8rem;
}

.floating-widget p strong {
    color: var(--text-heading);
    font-weight: 600;
}

/* New Boost Widget Styles - Light & Minimalist */
.boost-widget {
    background: rgba(255, 255, 255, 0.75);
    border: 1px solid rgba(0, 0, 0, 0.05);
    backdrop-filter: blur(12px);
    -webkit-backdrop-filter: blur(12px);
    box-shadow: 0 10px 40px rgba(0,0,0,0.1);
    animation: float 6s ease-in-out infinite;
    flex-direction: column;
    align-items: stretch;
    border-radius: 20px; /* Slightly smaller radius */
    padding: 18px; /* Tighter padding */
    width: 280px; /* Compact width */
    color: var(--text-dark);
    font-size: 0.9rem;
    transform: translateY(0);
}

.boost-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
}

.boost-header p {
    margin: 0;
    font-weight: 600;
    font-size: 0.95rem; /* Slightly smaller font */
    color: var(--text-heading);
}

.boost-widget hr {
    border: none;
    height: 1px;
    background-color: rgba(0, 0, 0, 0.08);
}

.status-pill {
    background-color: rgba(37, 99, 235, 0.1);
    color: var(--primary-blue);
    padding: 4px 10px;
    border-radius: 9999px;
    font-size: 0.8rem;
    font-weight: 500;
}

.boost-content {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 12px; /* Reduced margin */
}

.user-info {
    display: flex;
    align-items: center;
    gap: 10px;
}

.user-info img {
    width: 36px;
    height: 36px;
    border-radius: 50%;
}

.user-info span {
    font-weight: 500;
    color: var(--text-heading);
}

.boost-percentage-badge {
    background-color: #10B981; /* Yeşil */
    color: #ffffff;
    padding: 6px 12px;
    border-radius: 9999px;
    font-size: 0.85rem;
    font-weight: 600;
    box-shadow: 0 4px 10px rgba(16, 185, 129, 0.3);
}

.boost-action-button {
    background-color: var(--primary-blue);
    color: #ffffff;
    padding: 8px 14px;
    border-radius: 12px;
    display: flex;
    align-items: center;
    gap: 6px;
    font-weight: 500;
    font-size: 0.85rem;
    transition: all 0.3s ease;
    box-shadow: 0 4px 15px rgba(37, 99, 235, 0.2);
}

.boost-action-button:hover {
    transform: translateY(-2px);
    box-shadow: 0 6px 20px rgba(37, 99, 235, 0.3);
}

.boost-action-button i {
    font-size: 1rem;
}

.boost-footer {
    display: flex;
    justify-content: space-between;
    align-items: center;
    font-size: 0.8rem;
    color: var(--text-dark);
}

.progress-bar-segmented {
    width: 60%;
    height: 8px;
    background-color: #e2e8f0;
    border-radius: 4px;
    display: flex;
    gap: 2px;
    padding: 2px;
}

.progress-value {
    height: 100%;
    background-color: var(--primary-blue);
    border-radius: 2px;
    background-image: repeating-linear-gradient(
        to right,
        var(--primary-blue) 0,
        var(--primary-blue) 4px,
        transparent 4px,
        transparent 6px
    );
}


/* Individual Widget Positioning */
#widget1 { top: 15%; left: 5%; animation-delay: 0.2s; }
#widget2 { top: 20%; right: 7%; animation-delay: 0.5s; }
#widget3 { bottom: 35%; left: 7%; animation-delay: 0.8s; }
#widget4 { bottom: 30%; right: 5%; left: auto; animation-delay: 0.4s; }


@keyframes float {
    0%, 100% { transform: translateY(0); }
    50% { transform: translateY(-15px); }
}

/* Premium Orders Badge - Light Theme */
.orders-badge {
    display: inline-flex;
    align-items: center;
    gap: 15px;
    background: linear-gradient(145deg, rgba(255, 255, 255, 0.8), rgba(245, 247, 250, 0.85));
    backdrop-filter: blur(15px);
    -webkit-backdrop-filter: blur(15px);
    padding: 12px 25px;
    border-radius: 16px;
    margin-bottom: 30px;
    box-shadow: 0 10px 35px rgba(0,0,0,0.1), inset 0 -1px 1px rgba(0,0,0,0.05);
    position: relative;
    overflow: hidden;
    border: 1px solid rgba(0, 0, 0, 0.05);
}

.orders-badge::before {
    content: '';
    position: absolute;
    top: 0;
    left: 0;
    width: 150%;
    height: 100%;
    background: linear-gradient(110deg, transparent 40%, rgba(0, 0, 0, 0.04), transparent 60%);
    animation: premium-shine 5s linear infinite;
}

.badge-icon-wrapper {
    width: 40px;
    height: 40px;
    background: linear-gradient(145deg, var(--primary-blue), #1e40af);
    border-radius: 12px;
    display: flex;
    align-items: center;
    justify-content: center;
    color: white;
    font-size: 1.3rem;
    box-shadow: 0 4px 15px rgba(37, 99, 235, 0.3);
    flex-shrink: 0;
}

.orders-badge span {
    font-weight: 500;
    color: var(--text-dark);
    text-shadow: none;
}

.orders-badge span strong {
    font-weight: 700;
    color: var(--text-heading);
}

@keyframes premium-shine {
    from {
        transform: translateX(-70%);
    }
    to {
        transform: translateX(70%);
    }
}


.hero-content {
    background: radial-gradient(50% 50% at 50% 50%, #1548ff0f 0%, rgba(21, 72, 255, 0) 100%);
}

.hero-content h1 {
    font-size: 3.8rem;
    font-weight: 700;
    color: var(--text-heading);
    line-height: 1.2;
    margin-bottom: 20px;
}

.hero-content h1 span {
    color: var(--primary-blue);
}

.hero-content p {
    font-size: 1.1rem;
    max-width: 650px;
    margin: 0 auto 35px;
    line-height: 1.7;
    color: var(--text-dark);
}

.hero-actions {
    display: flex;
    justify-content: center;
    gap: 20px;
    margin-bottom: 30px;
}

.social-proof {
    font-size: 0.9rem;
    color: var(--text-dark);
    opacity: 0.8;
    margin-bottom: 40px; /* Added margin */
}

.social-proof {
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 15px;
    margin-bottom: 40px;
}

.avatars {
    display: flex;
}

.avatar-img {
    width: 40px;
    height: 40px;
    border-radius: 50%;
    border: 3px solid var(--light-bg);
    margin-left: -12px;
    object-fit: cover;
}

.avatar-img:first-child {
    margin-left: 0;
}

.proof-text {
    display: flex;
    align-items: center;
    gap: 8px;
    font-size: 0.95rem;
    color: var(--text-dark);
}

.star-icon {
    color: #f59e0b; /* Amber-500 */
    font-size: 1.2rem;
}

.proof-text strong {
    font-weight: 600;
    color: var(--text-heading);
}

/* Login Form */
.login-form-wrapper {
    background: rgba(255, 255, 255, 0.7);
    padding: 20px;
    border-radius: 30px;
    border: 1px solid rgba(0,0,0,0.05);
    backdrop-filter: blur(10px);
    -webkit-backdrop-filter: blur(10px);
    box-shadow: 0 10px 30px rgba(0,0,0,0.08);
    margin: 0 auto;
}

.login-form {
    display: flex;
    flex-direction: column;
    align-items: stretch;
    gap: 15px;
    width: 100%;
    max-width: 450px;
    margin-left: auto;
    margin-right: auto;
}

@media (min-width: 1024px) {
    .login-form {
        flex-direction: row;
        align-items: center;
        gap: 20px;
        max-width: none;
    }
}

.login-form .form-group {
    position: relative;
    flex-grow: 1;
}

.login-form input {
    width: 100%;
    height: 65px;
    padding: 0 25px 0 60px;
    border-radius: 22px;
    border: none;
    background-color: #edf2f7;
    color: var(--text-dark);
    font-size: 1.05rem;
    outline: none;
    transition: background-color 0.3s ease;
}

.login-form input:focus {
    background-color: #e2e8f0;
}

.login-form .form-group svg {
    position: absolute;
    left: 25px;
    top: 50%;
    transform: translateY(-50%);
    color: #a0aec0;
}

.login-form .btn-icon {
    width: 65px;
    height: 65px;
    display: flex;
    align-items: center;
    justify-content: center;
    background-color: #ffffff;
    border-radius: 22px;
    border: 1px solid #e2e8f0;
    color: #718096;
    transition: all 0.3s ease;
    flex-shrink: 0;
}

.login-form .btn-icon:hover {
    background-color: #e2e8f0;
    color: var(--primary-blue);
}

.login-form .btn-primary {
    height: 65px;
    padding: 0 45px;
    border-radius: 9999px;
    display: flex;
    align-items: center;
    justify-content: center;
}

.login-form .btn-primary span {
    font-weight: 600;
    font-size: 1.1rem;
}


/* Features Section */
.section-header {
    text-align: center;
    margin-bottom: 50px;
    background: radial-gradient(50% 50% at 50% 50%, #1548ff0f 0%, rgba(21, 72, 255, 0) 100%);
}

.section-badge {
    display: inline-flex;
    align-items: center;
    gap: 10px;
    background-color: rgba(37, 99, 235, 0.1);
    border: 1px solid rgba(37, 99, 235, 0.2);
    padding: 8px 16px;
    border-radius: 9999px;
    font-weight: 500;
    color: var(--primary-blue);
    margin-bottom: 20px;
}

.section-badge i {
    color: var(--primary-blue);
}

.section-header h2 {
    font-size: 2.5rem;
    font-weight: 700;
    color: var(--text-heading);
    margin-bottom: 15px;
}

.section-header h2 span {
    color: var(--primary-blue);
}

.section-header .subtitle {
    font-size: 1.1rem;
    max-width: 600px;
    margin: 0 auto;
    color: var(--text-dark);
    line-height: 1.6;
}

/* Features Grid - Unified & Corrected */
.features-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
    gap: 30px;
    margin-top: 50px;
}

.feature-card {
    background-color: var(--light-bg);
    background-image: url(https://i.hizliresim.com/6hvydwr.png);
    border: 1px solid var(--border-color);
    border-radius: 24px;
    padding: 30px;
    display: flex;
    flex-direction: column;
    transition: all 0.3s ease;
    box-shadow: 0 5px 25px rgba(0,0,0,0.03);
    text-align: left;
}

.feature-card:hover {
    transform: translateY(-5px);
    box-shadow: 0 10px 30px rgba(0,0,0,0.07);
    border-color: rgba(37, 99, 235, 0.2);
}

.feature-card .card-badge {
    display: inline-flex;
    align-items: center;
    gap: 10px;
    font-weight: 500;
    color: var(--primary-blue);
    background-color: rgba(37, 99, 235, 0.1);
    padding: 10px 20px;
    border-radius: 9999px;
    margin-bottom: 25px;
    border: 1px solid rgba(37, 99, 235, 0.2);
}

.feature-card .card-badge i {
    color: var(--primary-blue);
}

.feature-card h3 {
    font-size: 2.2rem;
    font-weight: 600;
    color: var(--text-heading);
    margin-bottom: 15px;
    line-height: 1.3;
}

.feature-card h3 .highlight-text {
    background: linear-gradient(45deg, var(--primary-blue), #3b82f6);
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
    background-clip: text;
}

.feature-card p {
    font-size: 1rem;
    line-height: 1.7;
    color: var(--text-dark);
    margin-bottom: 25px;
    flex-grow: 1;
}

.feature-card.text-center-card {
    text-align: center;
}

.feature-card.text-center-card .card-badge {
    align-self: center;
}

.card-icons-wrapper {
    overflow: hidden;
    padding: 10px 0;
    margin-top: auto;
    display: flex;
    flex-direction: column;
    gap: 15px;
    position: relative;
}

.card-icons-wrapper::before,
.card-icons-wrapper::after {
    content: '';
    position: absolute;
    top: 0;
    bottom: 0;
    width: 50px;
    z-index: 2;
    pointer-events: none;
}

.card-icons-wrapper::before {
    left: 0;
    background: linear-gradient(to right, var(--light-bg), transparent);
}

.card-icons-wrapper::after {
    right: 0;
    background: linear-gradient(to left, var(--light-bg), transparent);
}

.card-icons-row {
    display: flex;
    width: max-content;
    flex-shrink: 0;
    gap: 15px;
    transition: transform 0.5s ease-out; /* Add smooth transition */
}

.card-icon {
    width: 80px; /* Fixed width */
    height: 80px; /* Fixed height */
    border-radius: 16px;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 3.5rem;
    background-color: var(--secondary-bg);
    border: 1px solid var(--border-color);
    transition: all 0.2s ease-in-out;
    flex-shrink: 0; /* Prevent shrinking */
}


.card-icon:hover {
    transform: scale(1.05);
    border-color: var(--primary-blue);
}

/* Brand colors for icons, not background */
.card-icon.tiktok i { color: #000000; }
.card-icon.twitch i { color: #9146FF; }
.card-icon.telegram i { color: #24A1DE; }
.card-icon.youtube i { color: #FF0000; }
.card-icon.soundcloud i { color: #ff5500; }
.card-icon.spotify i { color: #1DB954; }
.card-icon.discord i { color: #5865F2; }
.card-icon.whatsapp i { color: #25D366; }
.card-icon.twitter i { color: #14171A; }
.card-icon.linkedin i { color: #0A66C2; }

.card-icon.facebook i { color: #1877F2; }
.card-icon.instagram i { color: #E4405F; }





/* Support Card */
.support-card {
    position: relative;
    overflow: hidden;
    justify-content: flex-end;
}

.support-elements {
    height: 200px;
    position: relative;
    margin-bottom: 20px;
    display: flex;
    justify-content: center;
    align-items: center;
}

.support-logo {
    width: 100px;
    height: 100px;
    background: var(--primary-blue);
    color: white;
    border-radius: 24px;
    display: flex;
    justify-content: center;
    align-items: center;
    font-size: 3.5rem;
    box-shadow: 0 10px 25px rgba(37, 99, 235, 0.3);
    transform: rotate(-15deg);
}

.chat-bubble {
    position: absolute;
    background: var(--light-bg);
    padding: 12px 18px;
    border-radius: 14px;
    box-shadow: 0 8px 25px rgba(0,0,0,0.1);
    font-size: 0.9rem;
    max-width: 200px;
    line-height: 1.4;
    border: 1px solid var(--border-color);
}

.chat-1 {
    top: 10px;
    left: 0;
    transform: rotate(-8deg);
}

.status-icon {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 20px;
    height: 20px;
    border-radius: 50%;
    background-color: var(--primary-blue);
    color: white;
    margin-left: 5px;
    font-size: 0.8rem;
    float: right;
}

.chat-2 {
    top: 30px;
    right: 0;
    transform: rotate(6deg);
}

.chat-dots {
    bottom: 30px;
    right: 40px;
    transform: rotate(6deg);
    font-weight: 600;
}

.support-card-content {
    text-align: center;
    display: flex;
    flex-direction: column;
    align-items: center;
}
.support-card-content p {
    max-width: 450px;
}

.support-card .btn {
    align-self: center; /* Center the button */
}

.chat-bubble.chat-dots span {
    display: inline-block;
    width: 6px;
    height: 6px;
    border-radius: 50%;
    background-color: #b0b8c2;
    margin: 0 1px;
    animation: typing-dots 1.4s infinite ease-in-out;
    animation-fill-mode: both;
}

.chat-bubble.chat-dots span:nth-child(1) {
    animation-delay: 0s;
}

.chat-bubble.chat-dots span:nth-child(2) {
    animation-delay: 0.2s;
}

.chat-bubble.chat-dots span:nth-child(3) {
    animation-delay: 0.4s;
}

@keyframes typing-dots {
    0%, 80%, 100% {
        transform: scale(0.3);
        opacity: 1;
    }
    40% {
        transform: scale(1.0);
        opacity: 2;
    }
}


/* Footer */
.site-footer {
  background: linear-gradient(to bottom, #ffffff, #f8f9fa);
    color: var(--text-dark);
    padding: 60px 0 0;
    font-size: 0.95rem;
    border-top: 1px solid var(--border-color);
    position: relative;
    overflow: hidden;
}

.site-footer .container {
    position: relative;
    z-index: 1;
}

.site-footer::before,
.site-footer::after {
    content: "";
    position: absolute;
    width: 900px;
    height: 900px;
    border-radius: 50%;
    z-index: 0;
    pointer-events: none;
    background-repeat: no-repeat;
    background-image: 
        radial-gradient(circle, transparent 220px, rgba(37, 99, 235, 0.07) 220px, rgba(37, 99, 235, 0.07) 230px, transparent 230px),
        radial-gradient(circle, transparent 340px, rgba(37, 99, 235, 0.07) 340px, rgba(37, 99, 235, 0.07) 350px, transparent 350px);
    -webkit-mask-image: linear-gradient(to bottom, transparent 0%, black 40%, black 60%, transparent 100%);
    mask-image: linear-gradient(to bottom, transparent 0%, black 40%, black 60%, transparent 100%);
}

.site-footer::before {
    right: -500px;
    top: -250px;
    transform: rotate(0deg);
    left: auto;
}

.site-footer::after {
    left: -500px;
    bottom: -250px;
    top: auto;
    transform: rotate(0deg);
    right: auto;
}

.footer-top {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
    gap: 40px;
    padding-bottom: 40px;
    border-bottom: 1px solid var(--border-color);
}

.footer-column .logo {
    margin-bottom: 20px;
    color: var(--text-heading);
}

.footer-column.about p {
    line-height: 1.7;
    margin-bottom: 20px;
}

.contact-link {
    display: inline-flex;
    align-items: center;
    gap: 12px;
    background-color: transparent;
    padding: 0;
    border-radius: 0;
    transition: color 0.3s ease;
    color: var(--text-dark);
    font-weight: 500;
    text-decoration: none;
}

.contact-link:hover {
    color: var(--primary-blue);
}

.contact-link .icon-wrapper {
    width: 36px;
    height: 36px;
    display: flex;
    align-items: center;
    justify-content: center;
    background-color: var(--primary-blue);
    border-radius: 50%;
    font-size: 1.2rem;
    color: #ffffff;
}

.contact-link .email-text {
    flex-grow: 1;
}

.contact-link .ri-arrow-right-line {
    font-size: 1.3rem;
    transition: transform 0.3s ease, color 0.3s ease;
    color: inherit;
}

.contact-link:hover .ri-arrow-right-line {
    transform: translateX(4px);
}

.footer-column h4 {
    font-size: 1.1rem;
    color: var(--text-heading);
    margin-bottom: 25px;
    display: flex;
    align-items: center;
    gap: 10px;
}

.footer-column h4 i {
    color: var(--primary-blue);
    font-size: 1.3rem;
    font-weight: 100;
}

.footer-column ul li {
    margin-bottom: 15px;
}

.footer-column ul a {
    display: flex;
    align-items: center;
    gap: 8px;
    transition: all 0.3s ease;
}

.footer-column ul a:hover {
    color: var(--primary-blue);
    transform: translateX(5px);
}

.footer-column ul a i {
    color: var(--primary-blue);
    font-size: 1.2rem;
}

.footer-bottom {
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 25px 0;
    flex-wrap: wrap;
    gap: 20px;
}

.payment-methods {
    display: flex;
    gap: 15px;
}

.payment-methods span {
    font-size: 2rem;
    color: #a0aec0;
    transition: color 0.3s ease;
}

.payment-methods .ri-visa-line { color: #1A1F71; }
.payment-methods .ri-mastercard-line { color: #EB001B; }
.payment-methods .ri-paypal-line { color: #00457C; }
.payment-methods .ri-bit-coin-line { color: #F7931A; }

/* Responsive */
@media (max-width: 992px) {
    .features-grid { 
        grid-template-columns: 1fr;
    }
}

@media (max-width: 768px) {
    .header {
        position: static;
        padding: 15px 0;
    }
    .header-inner {
        flex-direction: row; /* Changed back to row for alignment */
        justify-content: space-between; /* Ensure logo and actions are spaced out */
        gap: 20px;
        border-radius: 20px;
        padding: 20px;
    }
    .header-actions {
        width: auto; /* Let it size based on content */
        display: flex; /* Use flex for the actions */
        gap: 12px;
    }
    .hero-content h1 {
        font-size: 2.5rem;
    }

    .hero-content p {
        font-size: 1rem;
    }

    .hero-actions {
        flex-direction: column;
        align-items: center;
    }
}

@media (max-width: 768px) {
  .floating-widget,
  .question-card {
    display: none !important;
  }
}

